import pathlib, subprocess, os, re
root=pathlib.Path('/home/labex/project')
def run(name,*args):
 return subprocess.run(['/bin/bash',str(root/name),*args],cwd=root,text=True,capture_output=True,timeout=2)
expected={'forward':('Forward',['Space Suits','Oxygen Tanks','Repair Kits']),'midship':('Midship',['Food Supplies','Water Containers','Medical Equipment']),'aft':('Aft',['Spare Parts','Fuel Cells','Scientific Instruments'])}
for bay,(label,items) in expected.items():
 p=run('cargo_manifest.sh',bay); assert p.returncode==0 and p.stdout==label+' Bay Inventory:\n'+''.join(str(i)+'. '+item+'\n' for i,item in enumerate(items,1))
assert run('cargo_manifest.sh').stdout=='Please specify a cargo bay: forward, midship, or aft\n'
assert run('cargo_manifest.sh','engine').stdout=='Invalid cargo bay. Choose forward, midship, or aft.\n'
